function checkCompileSupportRejectionReasonIsShared(errors) {
  const helperPath = path.join("src", "ts", "runtime", "compile_support.ts");
  const compilePath = path.join("src", "ts", "compile.ts");
  const moduleFacadePath = path.join("src", "ts", "runtime", "module_facade.ts");
  const executionPlanPath = path.join("src", "ts", "runtime", "execution_plan.ts");
  const moduleCompatibilityPath = path.join("src", "ts", "runtime", "module_compatibility.ts");
  const moduleCompilerPolicyPath = path.join("src", "ts", "runtime", "module_compiler_policy.ts");
  const singleModuleCompilePath = path.join("src", "ts", "nn", "single_module_compile.ts");
  const helperSource = fs.existsSync(path.join(root, helperPath))
    ? fs.readFileSync(path.join(root, helperPath), "utf8")
    : "";
  const compileSource = fs.readFileSync(path.join(root, compilePath), "utf8");
  const moduleFacadeSource = fs.readFileSync(path.join(root, moduleFacadePath), "utf8");
  const executionPlanSource = fs.readFileSync(path.join(root, executionPlanPath), "utf8");
  const moduleCompatibilitySource = fs.readFileSync(path.join(root, moduleCompatibilityPath), "utf8");
  const moduleCompilerPolicySource = fs.readFileSync(path.join(root, moduleCompilerPolicyPath), "utf8");
  const singleModuleCompileSource = fs.readFileSync(path.join(root, singleModuleCompilePath), "utf8");

  for (const needle of [
    "export type CompileSupportRejectionOptions = Readonly<{",
    "fallbackReason?: string;",
    "export function compileSupportRejectionReason(",
    "support: unknown,",
    "options: CompileSupportRejectionOptions = {},",
    "return options.fallbackReason ?? \"compileSupport did not return structured evidence\";",
    "return options.fallbackReason ?? \"compile target is unsupported\";",
  ]) {
    if (!helperSource.includes(needle)) {
      errors.push(`${helperPath} must own shared compile-support rejection diagnostics: ${needle}`);
    }
  }

  for (const [relativePath, source] of [
    [compilePath, compileSource],
    [moduleFacadePath, moduleFacadeSource],
    [executionPlanPath, executionPlanSource],
    [moduleCompatibilityPath, moduleCompatibilitySource],
    [moduleCompilerPolicyPath, moduleCompilerPolicySource],
    [singleModuleCompilePath, singleModuleCompileSource],
  ]) {
    if (!source.includes("compileSupportRejectionReason")) {
      errors.push(`${relativePath} must use the shared compile-support rejection diagnostic Module`);
    }
  }
  if (
    !compileSource.includes('from "./runtime/compile_support.js";') ||
    !compileSource.includes("compileSupportRejectionReason,")
  ) {
    errors.push(`${compilePath} must consume compile-support rejection diagnostics from src/ts/runtime/compile_support.ts`);
  }
  if (!moduleFacadeSource.includes('import { compileSupportRejectionReason } from "./compile_support.js";')) {
    errors.push(`${moduleFacadePath} must consume compile-support rejection diagnostics from src/ts/runtime/compile_support.ts`);
  }
  if (!executionPlanSource.includes('import { compileSupportRejectionReason } from "./compile_support.js";')) {
    errors.push(`${executionPlanPath} must consume compile-support rejection diagnostics from src/ts/runtime/compile_support.ts`);
  }
  if (!moduleCompatibilitySource.includes('import { compileSupportRejectionReason } from "./compile_support.js";')) {
    errors.push(`${moduleCompatibilityPath} must consume compile-support rejection diagnostics from src/ts/runtime/compile_support.ts`);
  }
  if (!moduleCompilerPolicySource.includes('import { compileSupportRejectionReason } from "./compile_support.js";')) {
    errors.push(`${moduleCompilerPolicyPath} must consume compile-support rejection diagnostics from src/ts/runtime/compile_support.ts`);
  }
  if (!singleModuleCompileSource.includes('import { compileSupportRejectionReason } from "../runtime/compile_support.js";')) {
    errors.push(`${singleModuleCompilePath} must consume compile-support rejection diagnostics from src/ts/runtime/compile_support.ts`);
  }
  if (!moduleFacadeSource.includes('fallbackReason: "module is unsupported by the native Program compiler"')) {
    errors.push(`${moduleFacadePath} must keep module-specific fallback wording at the call site`);
  }
  if (!executionPlanSource.includes('fallbackReason: "Module compile plan is not supported by the native Program compiler"')) {
    errors.push(`${executionPlanPath} must keep ModuleCompilePlan fallback wording at the call site`);
  }
  if (!moduleCompatibilitySource.includes('fallbackReason: "module is unsupported by the native Program compiler"')) {
    errors.push(`${moduleCompatibilityPath} must keep module compatibility fallback wording at the call site`);
  }
  if (!moduleCompilerPolicySource.includes("return compileSupportRejectionReason(artifacts, { fallbackReason: fallback });")) {
    errors.push(`${moduleCompilerPolicyPath} must reuse shared compile-support diagnostics for trace compiler unsupported reasons`);
  }

  const localFunctionPattern = /function\s+compileSupportRejectionReason\s*\(/g;
  if ((compileSource.match(localFunctionPattern) || []).length > 0) {
    errors.push(`${compilePath} must not re-own compile-support rejection diagnostics`);
  }
  if ((moduleFacadeSource.match(localFunctionPattern) || []).length > 0) {
    errors.push(`${moduleFacadePath} must not re-own compile-support rejection diagnostics`);
  }
  if (executionPlanSource.includes("function moduleCompilePlanReason(")) {
    errors.push(`${executionPlanPath} must not re-own ModuleCompilePlan rejection diagnostics`);
  }
  for (const [relativePath, source] of [
    [moduleCompatibilityPath, moduleCompatibilitySource],
    [singleModuleCompilePath, singleModuleCompileSource],
  ]) {
    if (source.includes('|| "module is unsupported by the native Program compiler"') || source.includes(".reason || fallbackReason")) {
      errors.push(`${relativePath} must not hand-roll module compile-support fallback reasons`);
    }
  }
}

