function checkPackageEntryOrderingIsStable(errors) {
  const packageMetadataPolicySource = fs.readFileSync(path.join(root, "scripts", "package_metadata_policy.cjs"), "utf8");
  if (!packageMetadataPolicySource.includes("function packageEntryOrder") || !packageMetadataPolicySource.includes("function packageEntryDepth")) {
    errors.push("scripts/package_metadata_policy.cjs must sort package entries by path depth so public subpath declarations keep stable dist names");
  }
}

function checkTsdownOwnsPackageFanout(errors) {
  const tsdownConfigSource = fs.readFileSync(path.join(root, "tsdown.config.mjs"), "utf8");
  const declarationGeneratorSource = fs.readFileSync(path.join(root, "scripts", "generate_package_declarations.cjs"), "utf8");
  for (const needle of requiredTsdownConfigContracts) {
    if (!tsdownConfigSource.includes(needle)) {
      errors.push(`tsdown.config.mjs must preserve TS-owned package fan-out from src/ts/** through tsdown: ${needle}`);
    }
  }
  for (const needle of requiredDeclarationGeneratorContracts) {
    if (!declarationGeneratorSource.includes(needle)) {
      errors.push(`scripts/generate_package_declarations.cjs must emit unbundled TS-owned package declarations: ${needle}`);
    }
  }
  if (/entry\s*:\s*["'`][^"'`]+["'`]/.test(tsdownConfigSource)) {
    errors.push("tsdown.config.mjs must not collapse package runtime output to one manual entry; derive package entries from src/ts/**");
  }
  for (const forbiddenRef of forbiddenTsdownConfigRefs) {
    if (tsdownConfigSource.includes(forbiddenRef)) {
      errors.push(`tsdown.config.mjs must not use generated or hand-written JS package sources: ${forbiddenRef}`);
    }
  }
}

