function checkBunAbiWordWritersAreShared(errors) {
  const helperPath = path.join(root, "src", "ts", "adapters", "bun_abi_words.ts");
  if (!fs.existsSync(helperPath)) {
    errors.push("Bun ABI word writers must live in src/ts/adapters/bun_abi_words.ts");
    return;
  }
  const helperSource = fs.readFileSync(helperPath, "utf8");
  for (const needle of ["setUSize", "setPtr", "setU32", "view.setBigUint64"]) {
    if (!helperSource.includes(needle)) {
      errors.push(`src/ts/adapters/bun_abi_words.ts must own Bun ABI word writer ${needle}`);
    }
  }

  const checkedFiles = fs.readdirSync(path.join(root, "src", "ts", "adapters"))
    .filter((name) => name.startsWith("bun_") && name.endsWith(".ts") && name !== "bun_abi_words.ts")
    .map((name) => path.join("src", "ts", "adapters", name));
  for (const relativePath of checkedFiles) {
    const source = fs.readFileSync(path.join(root, relativePath), "utf8");
    const localWriters = [
      "function setUSize(",
      "function setPtr(",
      "view.setBigUint64(",
    ].filter((needle) => source.includes(needle));
    if (localWriters.length > 0) {
      errors.push(`${relativePath} must use src/ts/adapters/bun_abi_words.ts instead of local Bun ABI word writers: ${localWriters.join(", ")}`);
    }
    if (
      source.includes("BigUint64Array") &&
      source.includes("new DataView(") &&
      !source.includes("./bun_abi_words.js") &&
      relativePath !== path.join("src", "ts", "adapters", "bun_ffi_bootstrap.ts")
    ) {
      errors.push(`${relativePath} packs Bun ABI descriptors and must import shared bun_abi_words helpers`);
    }
  }
}

