  if (!nodeHelperSource.includes('from "../runtime/llama_kv_cache.js"') || !nodeHelperSource.includes("createNodeLlamaKvCacheOps")) {
    errors.push("node_llama_kv_cache_ops.ts must be a Node adapter over runtime-owned LLaMA KV-cache allocation/resource policy");
  }
  if (!nodeHelperSource.includes("export type NodeLlamaKvCacheOpsOptions") || !nodeHelperSource.includes("Readonly<")) {
    errors.push("node_llama_kv_cache_ops.ts must expose a named readonly NodeLlamaKvCacheOpsOptions Adapter Interface");
  }
  if (nodeSurfaceSource.includes("@ts-nocheck")) {
    errors.push("node_llama_kv_cache_surface.ts must stay typechecked; do not reintroduce @ts-nocheck");
  }
  if (nodeFactorySurfaceSource === "") {
    errors.push("node_llama_kv_cache_factory_surface.ts must own typed Node LLaMA KV-cache factory policy");
  }
  if (nodeFactorySurfaceSource.includes("@ts-nocheck")) {
    errors.push("node_llama_kv_cache_factory_surface.ts must stay typechecked; do not reintroduce @ts-nocheck");
  }
  for (const needle of [
    "export type NodeLlamaKvCacheFactorySurfaceOptions<TBuffer, TKvCache>",
    "export function createNodeLlamaKvCacheFactorySurface<TBuffer, TKvCache>",
    "getNativeBufferClass(): NativeBufferFactory<TBuffer>",
    "getKvCacheClass(): LlamaKvCacheConstructor<TBuffer, TKvCache>",
    "return options.getNativeBufferClass().create(byteLength)",
    "return new LlamaKvCache(k, v)",
  ]) {
    if (!nodeFactorySurfaceSource.includes(needle)) {
      errors.push(`node_llama_kv_cache_factory_surface.ts must own typed Node LLaMA KV-cache factory policy: missing ${needle}`);
    }
  }
  if (
    !nodeSurfaceSource.includes("export function createNodeLlamaKvCacheClass") ||
    !nodeSurfaceSource.includes("export type NodeLlamaKvCacheSurface") ||
    !nodeSurfaceSource.includes("for (const buffer of this.k) buffer.free();") ||
    !nodeSurfaceSource.includes("for (const buffer of this.v) buffer.free();")
  ) {
    errors.push("node_llama_kv_cache_surface.ts must own the typed Node LLaMA KV-cache class lifecycle");
  }
  if (!bunHelperSource.includes("export type BunLlamaKvCacheOpsOptions")) {
    errors.push("bun_llama_kv_cache_ops.ts must expose a named BunLlamaKvCacheOpsOptions Adapter Interface");
  }
  if (bunSurfaceSource === "") {
    errors.push("bun_llama_kv_cache_surface.ts must own the typed Bun LLaMA KV-cache class lifecycle");
  }
  if (bunSurfaceSource.includes("@ts-nocheck")) {
    errors.push("bun_llama_kv_cache_surface.ts must stay typechecked; do not reintroduce @ts-nocheck");
  }
  for (const needle of [
    "export type BunLlamaKvCacheSurfaceOptions<TNativeBuffer extends NativeBufferLike>",
    "export type BunLlamaKvCacheConstructor<TNativeBuffer extends NativeBufferLike>",
    "export function createBunLlamaKvCacheClass<TNativeBuffer extends NativeBufferLike>",
    "const buffers = options.createLlamaKvCacheBuffers(",
    "options.freeKvCacheBuffers(this.k, this.v);",
    "this.k = [];",
    "this.v = [];",
    "[Symbol.dispose](): void",
  ]) {
    if (!bunSurfaceSource.includes(needle)) {
      errors.push(`bun_llama_kv_cache_surface.ts must own the typed Bun LLaMA KV-cache class lifecycle: missing ${needle}`);
    }
  }
  for (const [label, source] of [
    ["bun_llama_kv_cache_ops.ts", bunHelperSource],
    ["node_llama_kv_cache_ops.ts", nodeHelperSource],
  ]) {
    const duplicated = [
      /function\s+createLlamaKvCacheBuffers\s*\(/,
      /llamaKvCacheResourceSlot\s*\(/,
    ].filter((pattern) => pattern.test(source));
    if (duplicated.length > 0) {
      errors.push(`${label} must not duplicate shared LLaMA KV-cache allocation/resource policy`);
    }
  }
  if (!nodeRuntimeSource.includes('require("./node_llama_kv_cache_ops.js")') || !nodeRuntimeSource.includes("createNodeLlamaKvCacheOps")) {
    errors.push("node_ffi_runtime.ts must use the TS-owned Node LLaMA KV-cache allocation helper policy");
  }
  if (!nodeRuntimeSource.includes('require("./node_llama_kv_cache_surface.js")') || !nodeRuntimeSource.includes("createNodeLlamaKvCacheClass")) {
    errors.push("node_ffi_runtime.ts must use the typed Node LLaMA KV-cache surface Module");
  }
  if (!nodeRuntimeSource.includes('require("./node_llama_kv_cache_factory_surface.js")') || !nodeRuntimeSource.includes("createNodeLlamaKvCacheFactorySurface({")) {
    errors.push("node_ffi_runtime.ts must use the typed Node LLaMA KV-cache factory surface Module");
  }
  if (/class\s+LlamaKvCache\b/.test(nodeRuntimeSource)) {
    errors.push("node_ffi_runtime.ts must not define the Node LLaMA KV-cache class inside the unchecked concrete runtime");
  }
  const forbiddenNodeFactorySurface = [
    /createNativeBuffer:\s*\(byteLength\)\s*=>\s*NativeBuffer\.create\(byteLength\)/,
    /createKvCache:\s*\(k,\s*v\)\s*=>\s*new LlamaKvCache\(k,\s*v\)/,
  ].filter((pattern) => pattern.test(nodeRuntimeSource));
  if (forbiddenNodeFactorySurface.length > 0) {
    errors.push("node_ffi_runtime.ts must not define Node LLaMA KV-cache factory callbacks inside the unchecked concrete runtime");
  }
  if (!bunRuntimeSource.includes('from "./bun_llama_kv_cache_ops.js"') || !bunRuntimeSource.includes("createBunLlamaKvCacheOps")) {
    errors.push("bun_ffi_runtime.ts must use the TS-owned Bun LLaMA KV-cache allocation helper policy");
  }
  if (!bunRuntimeSource.includes('from "./bun_llama_kv_cache_surface.js"') || !bunRuntimeSource.includes("createBunLlamaKvCacheClass<NativeBuffer>({")) {
    errors.push("bun_ffi_runtime.ts must use the typed Bun LLaMA KV-cache surface Module");
  }
  if (/class\s+LlamaKvCache\b/.test(bunRuntimeSource)) {
    errors.push("bun_ffi_runtime.ts must not define the Bun LLaMA KV-cache class inside the concrete runtime");
  }
  const bunClassStart = bunRuntimeSource.indexOf("export class LlamaKvCache");
  const bunClassEnd = bunRuntimeSource.indexOf("function createProgramLlamaKvCache", bunClassStart);
  const bunClassSource = bunClassStart >= 0 && bunClassEnd > bunClassStart ? bunRuntimeSource.slice(bunClassStart, bunClassEnd) : "";
  const nodeClassStart = nodeRuntimeSource.indexOf("class LlamaKvCache");
  const nodeClassEnd = nodeRuntimeSource.indexOf("function createProgramLlamaKvCache", nodeClassStart);
  const nodeClassSource = nodeClassStart >= 0 && nodeClassEnd > nodeClassStart ? nodeRuntimeSource.slice(nodeClassStart, nodeClassEnd) : "";
  const forbidden = [
    /llamaKvCacheResourceFactory\s*\(/,
    /llamaKvCacheResourceSlot\s*\(/,
    /assertLlamaKvCacheResourceByteLength\s*\(/,
    /for\s*\(\s*let\s+layer\s*=\s*0;\s*layer\s*<\s*requirements\.layers/,
  ];
  if (forbidden.filter((pattern) => pattern.test(nodeClassSource)).length > 0) {
    errors.push("node_ffi_runtime.ts LlamaKvCache class must not re-own allocation/resource helper policy");
  }
  if (forbidden.filter((pattern) => pattern.test(bunClassSource)).length > 0) {
    errors.push("bun_ffi_runtime.ts LlamaKvCache class must not re-own allocation/resource helper policy");
  }
