function checkZigRootClassifiesNativeSubstrate(errors) {
  const sourcePath = path.join(root, "src", "main.zig");
  const source = fs.existsSync(sourcePath) ? fs.readFileSync(sourcePath, "utf8") : "";
  for (const needle of [
    "const native_manifest = @import(\"native_substrate_manifest.zig\");",
    "pub const native_substrate_manifest = native_manifest.native_substrate_manifest;",
    "\"native_substrate_manifest\"",
    "try testing.expectEqualStrings(\"zgml-native-substrate\", native_substrate_manifest.kind)",
    "try testing.expectEqualStrings(\"core-kernel-runtime\", native_substrate_manifest.role)",
    "try testing.expectEqualStrings(\"typescript\", native_substrate_manifest.product_language)",
    "try testing.expectEqualStrings(\"src/ts/**\", native_substrate_manifest.product_source)",
    "try testing.expectEqualStrings(\"ts-api-zig-core\", native_substrate_manifest.product_source_of_truth)",
    "try testing.expectEqualStrings(\"tsdown\", native_substrate_manifest.package_fanout)",
    "try testing.expectEqualStrings(\"none\", native_substrate_manifest.frontend_sync)",
    "try testing.expectEqualStrings(\"JS/TS API -> Zig C ABI -> Program/Session kernels\", native_substrate_manifest.native_contract_boundary)",
    "try testing.expectEqualStrings(\"required-core\", native_substrate_manifest.native_product_policy)",
    "try testing.expectEqualStrings(\"zig-module-program\", native_substrate_manifest.module_compiler_core)",
    "try testing.expectEqualStrings(\"native-program-inspection\", native_substrate_manifest.native_compile_evidence)",
    "try testing.expectEqualStrings(\"zig-program-inspection\", native_substrate_manifest.program_inspection_core)",
  ]) {
    if (!source.includes(needle)) {
      errors.push(`src/main.zig must classify the Zig root as native substrate, not a mirrored package frontend: ${needle}`);
    }
  }

  if (source.includes("pub const native_substrate_manifest = .{")) {
    errors.push("src/main.zig must not hand-copy the native substrate manifest; import src/native_substrate_manifest.zig generated from src/ts/frontend_manifest.ts");
  }
}

function checkNativeSubstrateManifestIsGenerated(errors) {
  const generatedPath = path.join(root, "src", "native_substrate_manifest.zig");
  const generatedSource = fs.existsSync(generatedPath) ? fs.readFileSync(generatedPath, "utf8") : "";
  for (const needle of [
    "Generated from src/ts/frontend_manifest.ts by scripts/generate_native_substrate_manifest.cjs.",
    "TS owns product policy, Zig imports this native substrate view.",
    "pub const native_substrate_manifest = .{",
    ".kind = \"zgml-native-substrate\"",
    ".role = \"core-kernel-runtime\"",
    ".product_language = \"typescript\"",
    ".product_source = \"src/ts/**\"",
    ".product_source_of_truth = \"ts-api-zig-core\"",
    ".product_semantics_owner = \"src/ts/** + src/**/*.zig\"",
    ".package_fanout = \"tsdown\"",
    ".frontend_sync = \"none\"",
    ".handwritten_frontend_mirrors = false",
    ".native_alignment = \"zig-core-contract-tested\"",
    ".native_product_policy = \"required-core\"",
    ".native_contract_boundary = \"JS/TS API -> Zig C ABI -> Program/Session kernels\"",
    ".module_compiler_core = \"zig-module-program\"",
    ".native_compile_evidence = \"native-program-inspection\"",
    ".program_inspection_core = \"zig-program-inspection\"",
  ]) {
    if (!generatedSource.includes(needle)) {
      errors.push(`src/native_substrate_manifest.zig must preserve the TS-generated native substrate manifest: ${needle}`);
    }
  }

  try {
    execFileSync(process.execPath, ["scripts/generate_native_substrate_manifest.cjs", "--check"], {
      cwd: root,
      stdio: "pipe",
    });
  } catch (error) {
    const stderr = error.stderr ? String(error.stderr).trim() : "";
    errors.push(stderr || "src/native_substrate_manifest.zig must match src/ts/frontend_manifest.ts");
  }
}

function checkZigHelpersClassifiedAsNativeHelpers(errors) {
  const requiredHeaders = {
    "src/nn.zig": {
      header: "//! Native neural-network helpers that decompose into primitive tensor ops.",
      domain: "nn",
    },
    "src/loss.zig": {
      header: "//! Native loss helpers over Tensor primitives.",
      domain: "loss",
    },
    "src/optim.zig": {
      header: "//! Native imperative optimizer helpers over trainable Tensor parameters.",
      domain: "optim",
    },
    "src/train.zig": {
      header: "//! Native training-loop helpers over ComputeGraph, Tensor losses, and optimizers.",
      domain: "train",
    },
  };
  for (const [relativePath, { header: expectedHeader, domain }] of Object.entries(requiredHeaders)) {
    const sourcePath = path.join(root, relativePath);
    const source = fs.existsSync(sourcePath) ? fs.readFileSync(sourcePath, "utf8") : "";
    if (!source.includes(expectedHeader)) {
      errors.push(`${relativePath} must classify itself as a native helper surface, not the TS package product owner: ${expectedHeader}`);
    }
    for (const needle of [
      "pub const native_helper_manifest = .{",
      '.kind = "zgml-native-helper"',
      `.domain = "${domain}"`,
      ".product_frontend = false",
      '.product_owner = "src/ts/**"',
      '.product_policy = "required-core"',
      '.role = "native-helper-substrate"',
      '.alignment_boundary = "JS/TS API -> Zig C ABI -> Program/Session kernels"',
      '"native_helper_manifest"',
      'try testing.expectEqualStrings("zgml-native-helper", native_helper_manifest.kind)',
      `try testing.expectEqualStrings("${domain}", native_helper_manifest.domain)`,
      "try testing.expectEqual(false, native_helper_manifest.product_frontend)",
      'try testing.expectEqualStrings("src/ts/**", native_helper_manifest.product_owner)',
      'try testing.expectEqualStrings("required-core", native_helper_manifest.product_policy)',
      'try testing.expectEqualStrings("native-helper-substrate", native_helper_manifest.role)',
      'try testing.expectEqualStrings("JS/TS API -> Zig C ABI -> Program/Session kernels", native_helper_manifest.alignment_boundary)',
    ]) {
      if (!source.includes(needle)) {
        errors.push(`${relativePath} must expose native-helper manifest evidence instead of acting as a mirrored product frontend: ${needle}`);
      }
    }
    for (const forbidden of [
      "named frontend helper",
      "Interface stays curated",
      "Canonical neural-network helpers",
      "Curated loss functions",
      "Host-side imperative optimizers",
      "Small training-loop helpers",
    ]) {
      if (source.includes(forbidden)) {
        errors.push(`${relativePath} must not describe native helper policy as the package frontend: ${forbidden}`);
      }
    }
  }
  const mainSource = fs.readFileSync(path.join(root, "src", "main.zig"), "utf8");
  if (!mainSource.includes('test "native root surface stays curated"')) {
    errors.push("src/main.zig root test must describe the curated native surface, not a second public product frontend");
  }
  const buildSource = fs.readFileSync(path.join(root, "build.zig"), "utf8");
  for (const needle of [
    '.name = "native-helper-train-linear"',
    '.step_name = "native-helper-train-linear"',
    '.step_desc = "Run native helper linear-training smoke"',
  ]) {
    if (!buildSource.includes(needle)) {
      errors.push(`build.zig must classify the Zig training harness as a native helper smoke, not the public product API: ${needle}`);
    }
  }
  for (const forbidden of [
    '.name = "example-train-linear"',
    '.step_name = "example-train-linear"',
    "Run public linear-training example",
  ]) {
    if (buildSource.includes(forbidden)) {
      errors.push(`build.zig must not present Zig nn/training helpers as public product examples: ${forbidden}`);
    }
  }
  const trainExamplePath = path.join(root, "examples", "train_linear.zig");
  if (fs.existsSync(trainExamplePath)) {
    const trainExampleSource = fs.readFileSync(trainExamplePath, "utf8");
    if (!trainExampleSource.includes("Native helper smoke. Product-level model/training policy belongs in src/ts/**.")) {
      errors.push("examples/train_linear.zig must classify itself as native helper coverage; product training policy belongs in src/ts/**");
    }
  }
}

